package nl.slimov.app;
import android.content.Context;import android.security.keystore.*;import android.util.Base64;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;import java.security.KeyStore;import java.nio.charset.StandardCharsets;
/** The NS key is encrypted with a device-local Android Keystore key, never returned to JS. */
public final class SecretStore {
 private static SecretKey key()throws Exception{KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);if(!ks.containsAlias("slimov.ns")){KeyGenerator generator=KeyGenerator.getInstance("AES","AndroidKeyStore");generator.init(new KeyGenParameterSpec.Builder("slimov.ns",KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());generator.generateKey();}return (SecretKey)ks.getKey("slimov.ns",null);}
 public static void set(Context c,String value)throws Exception{if(value.isEmpty()){c.getSharedPreferences("secrets",0).edit().clear().apply();return;}if(!value.matches("[A-Za-z0-9_-]{16,256}"))throw new Exception("Ongeldige API-sleutel");Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key());String iv=Base64.encodeToString(cipher.getIV(),Base64.NO_WRAP),body=Base64.encodeToString(cipher.doFinal(value.getBytes(StandardCharsets.UTF_8)),Base64.NO_WRAP);c.getSharedPreferences("secrets",0).edit().putString("ns",iv+":"+body).apply();}
 public static String get(Context c)throws Exception{String data=c.getSharedPreferences("secrets",0).getString("ns","");if(data.isEmpty())return "";String[] parts=data.split(":");Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Base64.decode(parts[0],Base64.NO_WRAP)));return new String(cipher.doFinal(Base64.decode(parts[1],Base64.NO_WRAP)),StandardCharsets.UTF_8);}
}
